window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cf31594367db49ed"]={"versions": [{"id": "FIG-cf31594367db49ed", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion (Protect) im AUTOSAR E2E-Protokoll (Profile 4 Forward). Das Diagramm beschreibt die algorithmische Abfolge innerhalb der E2E-Bibliothek beim Absichern von Nutzdaten vor der Übertragung über ein Kommunikationsmedium.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Aktionen und Entitäten:</p>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node) mit assoziierter Notiz bezüglich <code>CheckState</code> bzw. <code>[PRS_E2E_00597]</code>.\n</li><li>Vorprüfungs-Aktion: <code>Verify inputs of the protect function</code>.\n</li><li>Sequenzielle Teilschritte (jeweils als Unteraktivität/Call-Behavior-Aktion mit Verfeinerungssymbol gekennzeichnet): <code>Compute offset</code>, <code>Write Length</code>, <code>Write Counter</code>, <code>Write DataID</code>, <code>Protect_Compute CRC</code>, <code>Protect_Write CRC</code> und <code>Increment Counter</code>.\n</li><li>Drei Aktivitätsendknoten (Activity Final Nodes) mit Rückgabewerten bzw. Guards:\n<ul class=\"fig-list\"><li>Guard <code>[null input]</code> führt zum Endzustand mit Rückgabe/Status <code>E2E_E_INPUTERR_NULL</code>.\n</li><li>Guard <code>[wrong input]</code> führt zum Endzustand mit Rückgabe/Status <code>E2E_E_INPUTERR_WRONG</code>.\n</li><li>Regulärer Pfad führt zum Endzustand mit Rückgabewert <code>return E2E_E_OK</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt am Initialknoten und führt zur Eingangsvalidierung <code>Verify inputs of the protect function</code>.\n</li><li>Bei ungültigen Zeigern bzw. Null-Parametern (<code>[null input]</code>) verzweigt der Kontrollfluss direkt zum Abbruchknoten mit <code>E2E_E_INPUTERR_NULL</code>.\n</li><li>Bei unzulässigen Konfigurations- oder Parameterwerten (<code>[wrong input]</code>) verzweigt der Kontrollfluss zum Abbruchknoten mit <code>E2E_E_INPUTERR_WRONG</code>.\n</li><li>Bei erfolgreicher Validierung durchläuft die Funktion sequenziell folgende Schritte:\n<ul class=\"fig-list\"><li><code>Compute offset</code>: Berechnung des Byte-Offsets für den Header bzw. die Nutzdaten.\n</li><li><code>Write Length</code>: Schreiben des Längenfeldes in den Datenpuffer.\n</li><li><code>Write Counter</code>: Schreiben des aktuellen Zählerstandes (Sequence Counter).\n</li><li><code>Write DataID</code>: Einfügen bzw. Berücksichtigen des spezifischen Datenidentifikators.\n</li><li><code>Protect_Compute CRC</code>: Berechnung der Prüfsumme (CRC32) über Daten und Header.\n</li><li><code>Protect_Write CRC</code>: Eintragen des berechneten CRC-Wertes in die Zielnachricht.\n</li><li><code>Increment Counter</code>: Inkrementieren des Sequenzzählers für den nächsten Sendezyklus.\n</li></ul>\n</li><li>Nach fehlerfreiem Abschluss terminiert die Funktion mit dem Statuscode <code>return E2E_E_OK</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die dargestellte Abfolge definiert das normative Verhalten für E2E Profile 4 Sender/Schutz-Routinen gemäß AUTOSAR PRS E2E-Protocol. Implementierer müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li>Eingabeparameter vor jeder Datenmanipulation strikt geprüft werden und bei Fehlern sofort ohne Pufferveränderung abgebrochen wird.\n</li><li>Die Reihenfolge von Längen-, Zähler-, DataID- und CRC-Berechnung exakt eingehalten wird, um Interoperabilität zwischen unterschiedlichen Steuergeräten zu gewährleisten.\n</li><li>Der Zähler erst nach erfolgreicher Berechnung und Eintragung der Schutzdaten inkrementiert wird.\n</li></ul>"}, {"id": "FIG-4667080959077f03", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion (Protect) im AUTOSAR E2E-Protokoll (Profile 4 Forward). Das Diagramm beschreibt die algorithmische Abfolge innerhalb der E2E-Bibliothek beim Absichern von Nutzdaten vor der Übertragung über ein Kommunikationsmedium.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Aktionen und Entitäten:</p>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node) mit assoziierter Notiz bezüglich <code>CheckState</code> bzw. <code>[PRS_E2E_00597]</code>.\n</li><li>Vorprüfungs-Aktion: <code>Verify inputs of the protect function</code>.\n</li><li>Sequenzielle Teilschritte (jeweils als Unteraktivität/Call-Behavior-Aktion mit Verfeinerungssymbol gekennzeichnet): <code>Compute offset</code>, <code>Write Length</code>, <code>Write Counter</code>, <code>Write DataID</code>, <code>Protect_Compute CRC</code>, <code>Protect_Write CRC</code> und <code>Increment Counter</code>.\n</li><li>Drei Aktivitätsendknoten (Activity Final Nodes) mit Rückgabewerten bzw. Guards:\n<ul class=\"fig-list\"><li>Guard <code>[null input]</code> führt zum Endzustand mit Rückgabe/Status <code>E2E_E_INPUTERR_NULL</code>.\n</li><li>Guard <code>[wrong input]</code> führt zum Endzustand mit Rückgabe/Status <code>E2E_E_INPUTERR_WRONG</code>.\n</li><li>Regulärer Pfad führt zum Endzustand mit Rückgabewert <code>return E2E_E_OK</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt am Initialknoten und führt zur Eingangsvalidierung <code>Verify inputs of the protect function</code>.\n</li><li>Bei ungültigen Zeigern bzw. Null-Parametern (<code>[null input]</code>) verzweigt der Kontrollfluss direkt zum Abbruchknoten mit <code>E2E_E_INPUTERR_NULL</code>.\n</li><li>Bei unzulässigen Konfigurations- oder Parameterwerten (<code>[wrong input]</code>) verzweigt der Kontrollfluss zum Abbruchknoten mit <code>E2E_E_INPUTERR_WRONG</code>.\n</li><li>Bei erfolgreicher Validierung durchläuft die Funktion sequenziell folgende Schritte:\n<ul class=\"fig-list\"><li><code>Compute offset</code>: Berechnung des Byte-Offsets für den Header bzw. die Nutzdaten.\n</li><li><code>Write Length</code>: Schreiben des Längenfeldes in den Datenpuffer.\n</li><li><code>Write Counter</code>: Schreiben des aktuellen Zählerstandes (Sequence Counter).\n</li><li><code>Write DataID</code>: Einfügen bzw. Berücksichtigen des spezifischen Datenidentifikators.\n</li><li><code>Protect_Compute CRC</code>: Berechnung der Prüfsumme (CRC32) über Daten und Header.\n</li><li><code>Protect_Write CRC</code>: Eintragen des berechneten CRC-Wertes in die Zielnachricht.\n</li><li><code>Increment Counter</code>: Inkrementieren des Sequenzzählers für den nächsten Sendezyklus.\n</li></ul>\n</li><li>Nach fehlerfreiem Abschluss terminiert die Funktion mit dem Statuscode <code>return E2E_E_OK</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die dargestellte Abfolge definiert das normative Verhalten für E2E Profile 4 Sender/Schutz-Routinen gemäß AUTOSAR PRS E2E-Protocol. Implementierer müssen sicherstellen, dass:</p>\n<ul class=\"fig-list\"><li>Eingabeparameter vor jeder Datenmanipulation strikt geprüft werden und bei Fehlern sofort ohne Pufferveränderung abgebrochen wird.\n</li><li>Die Reihenfolge von Längen-, Zähler-, DataID- und CRC-Berechnung exakt eingehalten wird, um Interoperabilität zwischen unterschiedlichen Steuergeräten zu gewährleisten.\n</li><li>Der Zähler erst nach erfolgreicher Berechnung und Eintragung der Schutzdaten inkrementiert wird.\n</li></ul>"}], "trans": [{"from": "FIG-cf31594367db49ed", "to": "FIG-4667080959077f03", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
